ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    wsResponseConsultEvidentVerification: {
        wsResponseHeader: {
            system: {
                name: vars.attributes.name,
                correlationId: vars.attributes.correlationId,
                source: vars.attributes.source
            },
            service: {
                status: p('temDataServices.service.status.ok')
            }
        },
        evaluation: {
            header: {
                code: p('temDataServices.evaluation.header.code'),
                description: payload.validateQuestionnaireResponse.validateQuestionnaireResult.processResult
            },
            body: {
                result: payload.validateQuestionnaireResponse.validateQuestionnaireResult.validationResult,
                questionnaireId: "",
                approval: payload.validateQuestionnaireResponse.validateQuestionnaireResult.validateQuestionnaire,
                minPrgts: "",
                completedQuestions: "",
                securityCode: "",
                score: payload.validateQuestionnaireResponse.validateQuestionnaireResult.score,
                reaccess: "",
                approved100PercentOK: payload.validateQuestionnaireResponse.validateQuestionnaireResult.processResult
            }
        }
    }
}
